------------ import ------------
local KTool = CS.Engine.Lib.KTool
local cs_coroutine = require('XLua.cs_coroutine')
local Yielders = CS.Engine.Lib.Yielders
local Time = CS.UnityEngine.Time
------------ import ------------


------------ define ------------
local Image = typeof(CS.UnityEngine.UI.Image)
local Slider = typeof(CS.UnityEngine.UI.Slider)
local Text = typeof(CS.UnityEngine.UI.Text)
local TextMeshProUGUI = typeof(CS.TMPro.TextMeshProUGUI)
local UISliderMode = {
    None = 0,
    Image = 1,
    Slider = 2,
}
local UITextMode = {
    None = 0,
    Text = 1,
    TMP = 2,
}
------------ define ------------

--- from: Assets/BundleResources/Prefabs/UIBattling/BattleEnd/UIBattleEndBossDestroy.prefab
---@class SliderPro
---@field Env                           	SliderPro                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field Txt_Num                       	UnityEngine.RectTransform               

local SliderPro = Class("SliderPro")

------------ lifeCycle ------------
function SliderPro:Awake()
    self:CleanProperties()
    self:Init()
end

function SliderPro:OnDestroy()
    self:StopLerpProgress()
    self:CleanProperties()
end
------------ lifeCycle ------------

function SliderPro:CleanProperties()
    self.progress = nil
    self.minNum = nil
    self.maxNum = nil
    self.closeCo = nil
    self.lerpToValue = nil
    self.uiSliderMode = nil
    self.uiSlider = nil
    self.uiTextMode = nil
    self.uiText = nil
    self.defaultLerpCurve = nil
end

function SliderPro:Init()
    if isNotNull(self.controller) and isNotNull(self.controller.gameObject) then
        local image = self.controller.gameObject:GetComponent(Image)
        if not isNull(image) then
            self.uiSliderMode = UISliderMode.Image
            self.uiSlider = image
        end
        local slider = self.controller.gameObject:GetComponent(Slider)
        if not isNull(slider) then
            self.uiSliderMode = UISliderMode.Slider
            self.uiSlider = slider
        end
    end

    if not isNull(self.Txt_Num) then
        local text = self.Txt_Num.gameObject:GetComponent(Text)
        if not isNull(text) then
            self.uiTextMode = UITextMode.Text
            self.uiText = text
        end
        local tmp_text = self.Txt_Num.gameObject:GetComponent(TextMeshProUGUI)
        if not isNull(tmp_text) then
            self.uiTextMode = UITextMode.TMP
            self.uiText = tmp_text
        end
    end

    self.defaultLerpCurve = CS.UnityEngine.AnimationCurve.Linear(0,0,1,1)
    self.minNum = 0
    self.maxNum = 100
    self:SetProgress(0)
end

function SliderPro:SetMaxNum(maxNum)
    self.maxNum = maxNum
end

function SliderPro:SetProgress(progress)
    self:StopLerpProgress()

    self:SetUIProgress(progress)
    self.progress = progress
end

function SliderPro:LerpProgress(progress, duration, curve, onLerp, onLerpEnd)
    self:StopLerpProgress()
    self.lerpToValue = progress     -- 结束值缓存下来，强制结束的时候会用到

    local timer = 0
    local duration = duration
    local fromValue = self.progress
    local toValue = progress
    local curve = IsNull(curve) and self.defaultLerpCurve or curve
    if isNull(curve) then
        self:Init()
    end
    
    self.closeCo = cs_coroutine.start(function()
        while true do
            local t = timer / duration
            if t >= 1 then
                self:SetUIProgress(toValue)
                self.progress = toValue
                if not IsNull(onLerpEnd) then
                    onLerpEnd()
                end
                self.closeCo = nil
                return
            else
                timer = timer + Time.deltaTime
                local p = Mathf.Lerp(fromValue, toValue, curve:Evaluate(t))
                self:SetUIProgress(p)
                self.progress = p
                if not IsNull(onLerp) then
                    onLerp(p)
                end
                cs_coroutine.yield_return(Yielders.EndOfFrame)
            end
        end
    end)
end

function SliderPro:StopLerpProgress()
    if not isNull(self.closeCo) then
        cs_coroutine.stop(self.closeCo)
        self.closeCo = nil
    end
end

function SliderPro:ForceOverLerp()
    self:SetProgress(self.lerpToValue)
end

function SliderPro:SetUIProgress(progress)
    if isNull(self.uiSlider) then return end

    -- print("set slider value " .. tostring(progress))
    if self.uiSliderMode == UISliderMode.Image then
        self.uiSlider.fillAmount = progress
    elseif self.uiSliderMode == UISliderMode.Slider then
        self.uiSlider.value = progress
    end

    if isNull(self.uiText) then return end

    local maxNum = checkNumber(self.maxNum)
    self.uiText.text = tostring(checkInt(maxNum * progress))
end

return SliderPro